"use strict";(globalThis.webpackChunkmy_website=globalThis.webpackChunkmy_website||[]).push([[8276],{31261(i){i.exports=JSON.parse('{"tag":{"label":"\u2605\u2605\u2605\u2605\u2605","permalink":"/tags/\u2605\u2605\u2605\u2605\u2605","allTagsPath":"/tags","count":17,"items":[{"id":"theory/major-scale/index","title":"\u5927\u8abf\u97f3\u968e (Major Scale)","description":"\u6574\u7406\u5927\u8abf\u97f3\u968e\u7684\u6982\u5ff5","permalink":"/theory/major-scale/"},{"id":"theory/note-signature/index","title":"\u5347\u964d\u8a18\u865f","description":"\u6574\u7406\u5347\u964d\u8a18\u865f\u7684\u6982\u5ff5\u3002","permalink":"/theory/note-signature/"},{"id":"theory/guide-tone-revisited","title":"\u518d\u8ac7 Guide Tone","description":"\u5148\u524d\u63d0\u904e Guide Tone \u7684\u4e00\u4e9b\u89c0\u5ff5\uff0c\u628a\u540c\u6a23\u7684\u89c0\u5ff5\u5c0e\u5165\u9806\u968e\u548c\u5f26\u88e1\uff0c\u6211\u6574\u7406\u4e86\u4e00\u4e9b\u61c9\u7528\u65b9\u6cd5\uff0c\u4ee5 C \u5927\u8abf\u9806\u968e\u4e03\u548c\u5f26\u70ba\u4f8b\uff0c\u5982\u4e0b\uff1a","permalink":"/theory/guide-tone-revisited"},{"id":"guitar/guitar-chord-voicing/index","title":"\u5409\u4ed6\u7684\u548c\u5f26\u8072\u4f4d\u57fa\u672c\u6982\u5ff5","description":"\u6458\u8981\u548c\u5f26\u8072\u4f4d (Chord Voicing) \u7684\u57fa\u672c\u6982\u5ff5\u4ee5\u53ca\u5409\u4ed6\u7684\u61c9\u7528\u6280\u5de7\u3002","permalink":"/guitar/guitar-chord-voicing/"},{"id":"theory/secondary-dominat/index","title":"\u6b21\u5c6c\u548c\u5f26 (Secondary Dominant)","description":"\u6574\u7406\u6b21\u5c6c\u548c\u5f26\u7684\u57fa\u672c\u6982\u5ff5\u3001\u7d44\u6210\u3001\u8907\u5408\u548c\u5f26\u3001\u61c9\u7528 ... \u7b49\u6982\u5ff5\u3002","permalink":"/theory/secondary-dominat/"},{"id":"theory/modal-harmony","title":"\u6dfa\u8ac7 Modal Harmony (\u8abf\u5f0f\u548c\u8072)","description":"\u4e00\u822c\u7406\u89e3\u5927\u5c0f\u8abf\u548c\u8072\u6982\u5ff5\u90fd\u8981\u5f9e\u9806\u968e\u548c\u5f26\u958b\u59cb\uff0c\u9806\u968e\u548c\u5f26\u7684\u57fa\u672c\u5c31\u662f\u548c\u5f26\u6839\u97f3\u52a0\u4e0a\u5176\u4e09\u5ea6\u97f3\u7684\u5806\u758a\u96c6\u5408\u3002\u540c\u6a23\u7684\u9053\u7406\u4e5f\u53ef\u4ee5\u7528\u5728\u4e03\u500b\u8abf\u5f0f\u97f3\u968e\u88e1\uff0c\u7136\u5f8c\u627e\u5230\u5c6c\u65bc\u5404\u500b\u8abf\u5f0f\u7684\u548c\u8072\u7cfb\u7d71\u3002\u6574\u7406\u5404\u8abf\u5f0f\u7684\u9806\u968e\u548c\u5f26\u5982\u4e0b\u8868\uff1a","permalink":"/theory/modal-harmony"},{"id":"songs/ff10-2-memories-lightwaves","title":"\u6b4c\u66f2\u5206\u6790: FF10-2 - Memories of Lightwaves","description":"\u8457\u540d\u96fb\u73a9 Final Fantasy X-2 \u7684\u4e3b\u984c\u914d\u6a02\u4e4b\u4e00. Final Fantasy (\u4ee5\u4e0b\u7c21\u7a31 FF, \u5c31\u662f\u53f0\u7063\u65e9\u671f\u96dc\u8a8c\u7ffb\u8b6f\u6210 \\"\u592a\u7a7a\u6230\u58eb\\") \u96d6\u7136\u662f\u4e00\u6b3e RPG \u904a\u6232, \u4f46\u662f\u9664\u4e86\u904a\u6232\u672c\u8eab\u7684\u5287\u60c5\u6545\u4e8b, \u4eba\u7269, \u5834\u666f, \u904a\u6232\u65b9\u5f0f\u7684\u5275\u610f, \u6700\u4ee4\u73a9\u5bb6\u6d25\u6d25\u6a02\u9053\u4e4b\u4e00\u7684\u5c31\u662f\u4ed6\u7684\u904a\u6232\u914d\u6a02, \u7531\u65e5\u672c\u8457\u540d\u7684\u914d\u6a02\u5927\u5e2b\u690d\u677e\u4f38\u592b (Nobuo Uematsu) \u8b5c\u66f2. FF \u97f3\u6a02\u76f8\u95dc\u7684\u8cc7\u8a0a\u6211\u5c31\u4e0d\u591a\u8aaa\u4e86, Google \u53ef\u4ee5\u627e\u5230\u5f88\u591a\u76f8\u95dc\u8cc7\u8a0a.","permalink":"/songs/ff10-2-memories-lightwaves"},{"id":"theory/modal-interchange","title":"\u8abf\u5f0f\u5167\u8f49 (Modal Interchange)","description":"\u8abf\u5f0f\u5167\u8f49 (Modal Interchange\uff0c\u4e5f\u6709\u66f8\u672c\u7ffb\u8b6f\u6210 \u501f\u7528\u548c\u5f26\u3001\u8abf\u5f0f\u4e92\u63db) \u662f\u4e00\u7a2e\u548c\u8072\u6280\u5de7\uff0c\u7c21\u55ae\u8aaa\u5c31\u662f\u5927\u5c0f\u8abf\u548c\u8072\u7684\u501f\u7528\u3001\u4ee3\u63db\u6280\u5de7\u3002\u53ef\u4ee5\u8b93\u4ee5\u8abf\u70ba\u4e2d\u5fc3\u7684\u6b4c\u66f2\u5728\u9032\u884c\u4e2d\u88fd\u9020\u51fa\u985e\u4f3c\u8f49\u8abf\u7684\u611f\u89ba\u3001\u548c\u5f35\u529b\uff0c\u4f46\u537b\u4e0d\u662f\u5927\u6bb5\u843d\u7684\u8f49\u8abf\u3002\u4ed6\u7684\u611f\u89ba\u4e0d\u50cf\u76f4\u63a5\u8f49\u8abf\u90a3\u6a23\u4e00\u76f4\u5ef6\u7e8c\u60c5\u7dd2\u3001\u537b\u7121\u6cd5\u5ef6\u7e8c\u5f35\u529b\uff0c\u4f46\u537b\u8b93\u6b4c\u66f2\u6709\u660e\u986f\u4e14\u6709\u6548\u7684\u5f35\u529b\u6548\u679c\u3002\u5c0d\u6b4c\u66f2\u4f86\u8aaa\uff0c\u53ef\u8aaa\u662f\u6709\u756b\u9f8d\u9ede\u775b\u7684\u6548\u679c\u3002","permalink":"/theory/modal-interchange"},{"id":"theory/mixolydian-mode-analysis","title":"\u7c21\u55ae\u7684 Mixolydian \u8abf\u5f0f\u5206\u6790","description":"\u672c\u6587\u662f\u6211\u6e96\u5099\u5728 Guitar \u9023\u7dda\u7248\u767c\u7684\u4e00\u7bc7\u95dc\u65bc\u8abf\u5f0f\u5206\u4eab\u7684\u5fc3\u5f97, \u6211\u628a\u4ed6\u6574\u7406\u597d\u653e\u5728\u9019\u88e1\u4f5c\u4e00\u500b\u7b46\u8a18.","permalink":"/theory/mixolydian-mode-analysis"},{"id":"theory/dominant-and-extension-chords/index","title":"\u5c6c\u4e03\u548c\u5f26\u8207\u5176\u5ef6\u4f38\u548c\u5f26\u7684\u4ee3\u63db","description":"\u5c6c\u4e03\u548c\u5f26 (Dominant 7th) \u662f\u5c6c\u65bc\u5927\u548c\u5f26\u7684\u5ef6\u4f38\uff0c\u4e5f\u5c31\u662f\u4ee5\u5927\u4e09\u548c\u5f26 (Major Triad) \u70ba\u57fa\u790e\uff0c\u7e7c\u7e8c\u4ee5\u4e09\u5ea6\u97f3\u5f80\u4e0a\u5806\u758a\u3002\u548c\u5f26\u7684\u5c6c\u6027\u5206\u985e\u4ee5\u4e09\u5ea6\u97f3\u548c\u4e03\u5ea6\u97f3\u4f5c\u70ba\u4e00\u500b\u5206\u754c\u9ede\uff0c\u66f4\u8a73\u7d30\u8acb\u53c3\u95b1 Guide Tone \u6216 Shell Chord \u7684\u4ecb\u7d39\u3002\u7e7c\u7e8c\u5f80\u4e0a\u5806\u758a\u5ef6\u4f38\u5247\u6703\u5f97\u5230\u6240\u8b02\u7684\u5ef6\u4f38\u548c\u5f26.","permalink":"/theory/dominant-and-extension-chords/"},{"id":"theory/altered-tension-notes/index","title":"\u8b8a\u5316\u5f15\u4f38\u97f3 (Altered Tension Notes)","description":"\u5728\u4e00\u822c\u8abf\u6027\u548c\u5f26 (Diatonic Chords\uff0c\u4e00\u822c\u5e38\u7ffb\u6210\u9806\u968e\u548c\u5f26) \u88e1\uff0c\u7c21\u55ae\u8aaa\u5c31\u662f\u4ee5\u8abf\u5167\u97f3\u7d44\u6210\u7684\u548c\u5f26\uff0c\u6709\u4e09\u548c\u5f26\u548c\u4e03\u548c\u5f26\u3002\u4ee5\u4e03\u548c\u5f26\u70ba\u4f8b\uff0c\u7d44\u6210\u97f3\u5c31\u662f 1357\u3002\u8d85\u51fa\u7d44\u6210\u97f3\u4ee5\u5916\u7684 9\u300111\u300113 \u90fd\u53eb\u505a Tension Notes (\u5f15\u4f38\u97f3)\uff0c\u5982\u4e0b\u5716\uff1a","permalink":"/theory/altered-tension-notes/"},{"id":"theory/drop-voicing/index","title":"Drop Voicing","description":"\u5728 Guide Tone \u7684\u4ecb\u7d39\u4e2d\u66fe\u63d0\u904e\u5982\u548c\u5b89\u6392\u4e03\u548c\u5f26\u7684 Voicing \uff0c\u53ef\u4ee5\u5229\u7528 Guide Tone \u7684\u7684\u89c0\u5ff5\u4f86\u8b93\u8072\u97ff\u66f4\u597d\u807d\u3002\u9664\u4e86\u5229\u7528 Guide tone \u7684\u89c0\u5ff5\uff0c\u9084\u6709\u53e6\u4e00\u7a2e\u6280\u5de7\u53ef\u4ee5\u8b93 Voicing \u66f4\u597d\u807d\uff0c\u5c31\u662f Drop Voicing\u3002","permalink":"/theory/drop-voicing/"},{"id":"guitar/ghost-pickup-system/index","title":"Graph Tech - Ghost Pickup System (\u5409\u4ed6\u6a21\u64ec\u7cfb\u7d71)","description":"\u9019\u662f\u7531 Graph Tech \u6240\u7814\u767c\u7684\u4e00\u5957\u985e\u4f3c VG99 \u7684\u5409\u4ed6\u6a21\u64ec\u7cfb\u7d71, \u4e3b\u8981\u5c31\u662f\u8b93\u96fb\u5409\u4ed6\u6709\u6bd4\u8f03 \\"\u64ec\u771f\\" \u7684\u6728\u5409\u4ed6\u7684\u97f3\u8272, \u53e6\u5916\u5c31\u662f\u8b93\u96fb\u5409\u4ed6\u4e5f\u80fd\u5920\u64c1\u6709\u8f38\u51fa MIDI \u8a0a\u865f\u7684\u529f\u80fd. \u4f46\u662f\u5f37\u8abf\u8f38\u51fa MIDI \u8a0a\u865f\u7684 Latency (\u5ef6\u9072) \u66f4\u77ed, \u66f4\u7cbe\u78ba. \u662f\u9664\u4e86 VG99 \u4ee5\u5916, \u53e6\u4e00\u500b\u8b93\u96fb\u5409\u4ed6\u6709 Acoustic Guitar \u548c MIDI \u4e0d\u932f\u7684\u9078\u64c7.","permalink":"/guitar/ghost-pickup-system/"},{"id":"theory/guide-tone","title":"Guide Tone","description":"\u4e09\u548c\u5f26 (Triad) \u7531\u6839\u97f3\u3001\u4e09\u5ea6\u97f3\u3001\u4e94\u5ea6\u97f3\u7d44\u6210\uff1a","permalink":"/theory/guide-tone"},{"id":"theory/misia-everything-analysis","title":"Misia - Everything \u6b4c\u66f2\u5206\u6790","description":"\u6211\u500b\u4eba\u975e\u5e38\u559c\u6b61\u7684\u66f2\u5b50, \u4e5f\u662f\u65e5\u5287 - \u5927\u548c\u62dc\u91d1\u5973\u7684\u4e3b\u984c\u66f2. \u6c92\u807d\u904e\u7684\u670b\u53cb\u53ef\u4ee5\u7dda\u4e0a\u807d\u770b\u770b (2002 Live , Studio \u7248\u672c), \u4e0d\u7ba1\u662f\u6b4c\u66f2\u672c\u8eab\u7684\u65cb\u5f8b, \u7c73\u897f\u4e9e (Misia) \u73fe\u5834\u7684\u5531\u529f (\u539f Key), \u548c\u8072\u7684\u5b89\u6392, \u90fd\u76f8\u7576\u7cbe\u91c7!","permalink":"/theory/misia-everything-analysis"},{"id":"theory/misia-everything-intro","title":"Misia - Everything \u6b4c\u66f2\u5206\u6790 (\u5e8f)","description":"Misia \u7684 Everything (\u65e5\u5287: \u5927\u548c\u62dc\u91d1\u5973\u4e3b\u984c\u66f2) \u4e00\u76f4\u662f\u6211\u5f88\u559c\u6b61\u7684\u6b4c\u66f2. \u60f3\u7576\u7136\u723e, \u53ea\u8981\u624b\u4e0a\u6709\u6a02\u5668\u5c31\u6703\u8ddf\u8457\u5f48.","permalink":"/theory/misia-everything-intro"},{"id":"theory/shell-chord","title":"Shell Chord","description":"Shell Chord (\u8c9d\u6bbc\u97f3) \u662f\u5409\u4ed6\u4e0a\u5f48\u594f\u5f15\u7533\u548c\u5f26\u5e38\u7528\u7684\u57fa\u790e\uff0c\u7d93\u5e38\u6703\u7528\u5728 Jazz\u3001Blues\u3001Funk\u3001Bossanova \u7b49\u97f3\u6a02\u88e1\u3002","permalink":"/theory/shell-chord"}],"unlisted":false}}')}}]);